const cfg = $('Rutas backup').item.json;
const out = $input.first().json;
const stdout = String(out.stdout ?? out ?? '');
const lines = stdout
  .split(/\r?\n/)
  .map((l) => l.replace(/^\uFEFF/, '').trim().replace(/^['"]|['"]$/g, ''))
  .filter(Boolean);
let zipPath = lines.reverse().find((l) => /\.zip$/i.test(l)) || '';
zipPath = zipPath.trim();

if (!zipPath || !/\.zip$/i.test(zipPath)) {
  throw new Error(
    `No se obtuvo ruta ZIP válida. stdout: ${stdout}. stderr: ${out.stderr ?? ''}`,
  );
}

const fileName = zipPath.split(/[/\\]/).pop();
const zipPathPosix = zipPath.replace(/\\/g, '/');

return [
  {
    json: {
      sourcePath: cfg.sourcePath,
      backupDir: cfg.backupDir,
      daysToKeep: Number(cfg.daysToKeep ?? 7),
      zipPath,
      zipPathPosix,
      fileName,
      ahora: new Date().toLocaleString('es-ES'),
    },
  },
];

